"""Compose a HarnessIR from layered templates.

For v0.1, this is intentionally minimal: it walks the resolved layers, classifies
files by directory structure (skills/, agents/, rules/, hooks/, memory.md, etc.),
renders Jinja templates with the config context, and constructs IR objects.

Per plan §15, tech-specific files arrive as scaffolds (frontmatter + TODO slots).
The composer does NOT validate body content here — that is the linter's job.
"""

from __future__ import annotations

import contextlib
import re
from datetime import UTC, datetime

from jinja2 import Environment

from harness import __version__ as _harness_version
from harness.compose.layers import Layer, existing_layers
from harness.config.models import HarnessConfig
from harness.ir.model import (
    AgentSpec,
    GenMeta,
    HarnessIR,
    HookSpec,
    MCPSpec,
    MemoryDoc,
    PermissionSet,
    ProjectMetaIR,
    RuleSpec,
    SkillSpec,
)
from harness.render.env import build_environment, is_jinja_template, list_templates

