def _split_frontmatter(text: str) -> tuple[dict, str]:
    """Parse YAML frontmatter from a markdown file. Returns (frontmatter, body).
    Returns ({}, text) when no frontmatter block is present."""
    m = _FRONTMATTER_RE.match(text)
    if not m:
        return {}, text
    from ruamel.yaml import YAML
    yaml = YAML(typ="safe")
    fm = yaml.load(m.group(1)) or {}
    body = m.group(2)
    return fm, body


def _build_context(config: HarnessConfig) -> dict:
    """Variables available to every Jinja template."""
    # Derive per-stack skill names. Every framework gets a `<framework>-patterns`
    # skill — composer auto-synthesises a placeholder if the stack overlay does
    # not ship one. Agents include these via Jinja in their `skills:` frontmatter
    # so subagents can load them at runtime (no implicit inheritance).
    all_patterns = sorted({f"{s.framework}-patterns" for s in config.stacks})
    # Validation skills derive from every stack's `test_runner`
    # (jest/vitest/pytest/playwright/maestro/cypress…) so validation-agent
    # always knows the runner the project actually uses. v0.2: roles dropped,
    # so we no longer specially treat `role: test-automation` stacks.
    # Exposed as `test_automation_patterns_skills` in Jinja context; consumed
    # exclusively by templates/base/agents/validation-agent.md.j2.
    test_automation_patterns = sorted({
        f"{s.test_runner}-patterns"
        for s in config.stacks
        if s.test_runner
    })
    return {
        "config": config,
        "project": config.project,
        "stacks": config.stacks,
        "integrations": config.integrations,
        "governance": config.governance,
        "model_routing": config.model_routing,
        "permissions": config.permissions,
        "outputs": config.outputs,
        # convenience flags (roles dropped v0.2; design/tracker flags remain)
        "has_design": config.integrations.design != "none",
        "has_jira": config.integrations.issue_tracker == "jira",
        "has_linear": config.integrations.issue_tracker == "linear",
        # tech-skill bindings (see plan §8 architectural law + scaffold-only policy)
        "stacks_patterns_skills": all_patterns,
        "test_automation_patterns_skills": test_automation_patterns,
    }


def compose_ir(
    config: HarnessConfig,
    layers: list[Layer],
    *,
    harness_version: str = _harness_version,
) -> HarnessIR:
    """Walk all template files, render via Jinja, classify into IR fields."""
    env = build_environment(layers)
    ctx = _build_context(config)
    template_files = list_templates(layers)

    skills: dict[str, SkillSpec] = {}
    agents: dict[str, AgentSpec] = {}
    rules: dict[str, RuleSpec] = {}
    memory: list[MemoryDoc] = []
    permissions = PermissionSet()
    hooks: list[HookSpec] = []
    mcp_servers: dict[str, MCPSpec] = {}
    hook_scripts: dict[str, str] = {}  # filename -> body
    settings_fragments: list[dict] = []
    mcp_fragments: list[dict] = []
    source_layers = [layer.label for layer in existing_layers(layers)]

    # Fragments are per-layer (not deduped) — every layer can contribute additively.
    # Render directly from each candidate file's bytes so Jinja's ChoiceLoader does not
    # collapse same-named fragments across layers.
    import json as _json
    for layer in existing_layers(layers):
        for fragment_name, target in (
            ("settings.fragment.json", settings_fragments),
            ("mcp.fragment.json", mcp_fragments),
        ):
            for cand in (layer.root / fragment_name, layer.root / f"{fragment_name}.j2"):
                if not cand.exists():
                    continue
                raw = cand.read_text(encoding="utf-8")
                rendered = env.from_string(raw).render(**ctx) if cand.suffix == ".j2" else raw
                with contextlib.suppress(_json.JSONDecodeError):
                    target.append(_json.loads(rendered))

    for rel in template_files:
        # Skip fragments — handled above by per-layer scan.
        if rel.endswith(("settings.fragment.json", "settings.fragment.json.j2",
                         "mcp.fragment.json", "mcp.fragment.json.j2")):
            continue

        body = _render_or_read(env, layers, rel, ctx)

        if rel.endswith(".keep"):
            continue

        out_rel = rel[:-3] if rel.endswith(".j2") else rel

        # Classify by path
        if out_rel == "CLAUDE.md":
            memory.append(MemoryDoc(scope="project", body=body))
            continue
        if out_rel.startswith("skills/") and out_rel.endswith("/SKILL.md"):
            skill = _build_skill_spec(out_rel, body)
            skills[skill.relative_dir] = skill
            continue
        # Supporting files alongside SKILL.md — collect into the skill's
        # `supporting_files` so the emitter writes them next to SKILL.md.
        if out_rel.startswith("skills/") and not out_rel.endswith("/SKILL.md"):
            parts = out_rel.split("/")
            # Find the longest prefix that is a registered skill dir.
            for i in range(len(parts) - 1, 1, -1):
                candidate_dir = "/".join(parts[:i])
                if candidate_dir in skills:
                    rel_to_skill = "/".join(parts[i:])
                    skills[candidate_dir].supporting_files[rel_to_skill] = body
                    break
            continue
        if out_rel.startswith("agents/") and out_rel.endswith(".md"):
            agent = _build_agent_spec(out_rel, body, default_model=config.model_routing.default)
            agent.model = config.model_routing.agents.get(agent.name, agent.model or config.model_routing.default)
            agents[agent.name] = agent
            continue
        if out_rel.startswith("rules/") and out_rel.endswith(".md"):
            rule = _build_rule_spec(out_rel, body)
            rules[rule.relative_path] = rule
            continue
        if out_rel.startswith("hooks/") and (out_rel.endswith(".mjs") or out_rel.endswith(".sh") or out_rel.endswith(".py")):
            filename = out_rel.split("/", 1)[1]
            hook_scripts[filename] = body
            continue

    # Merge settings fragments — collect deny/allow rules and hook entries
    for frag in settings_fragments:
        for rule in (frag.get("permissions", {}).get("allow") or []):
            if rule not in permissions.allow:
                permissions.allow.append(rule)
        for rule in (frag.get("permissions", {}).get("deny") or []):
            if rule not in permissions.deny:
                permissions.deny.append(rule)
        for event, entries in (frag.get("hooks") or {}).items():
            for entry in entries:
                matcher = entry.get("matcher")
                for handler in (entry.get("hooks") or []):
                    hooks.append(_hookspec_from_settings_entry(event, matcher, handler))

    # Auto-synthesise placeholder skills for any `<framework>-patterns` referenced
    # in agent frontmatter but missing from the template tree. Lets users supply
    # tech-specific knowledge by filling the body of these placeholders.
    referenced_skill_names: set[str] = set()
    for agent in agents.values():
        if agent.skills:
            referenced_skill_names.update(agent.skills)
    have_skill_names = {sk.name or sk.relative_dir.split("/")[-1] for sk in skills.values()}
    # Test-runner patterns (e.g. pytest-patterns) get a test-focused skeleton; framework
    # patterns get the full framework skeleton. Runner names are derived from each stack's
    # test_runner field at context-build time.
    runner_names = set(ctx.get("test_automation_patterns_skills") or [])
    for missing in sorted(referenced_skill_names - have_skill_names):
        # Only auto-synth `*-patterns` skills (the convention for tech overlays).
        if not missing.endswith("-patterns"):
            continue
        framework = missing.removesuffix("-patterns")
        rel_dir = f"skills/{missing}"
        is_runner = missing in runner_names
        tmpl = _RUNNER_PATTERNS_PLACEHOLDER_BODY if is_runner else _PATTERNS_PLACEHOLDER_BODY
        body = tmpl.format(framework=framework)
        if is_runner:
            description = (
                f"{framework} test patterns for this project — fill body with team test "
                f"conventions. Used by validation/arh-implementation agents."
            )
            when_to_use = f"Writing or reviewing {framework} tests."
        else:
            description = (
                f"{framework} patterns for this project — fill body with team conventions. "
                f"Used by implementation/validation/arh-review agents."
            )
            when_to_use = f"Writing or reviewing {framework} code."
        skills[rel_dir] = SkillSpec(
            name=missing,
            description=description,
            when_to_use=when_to_use,
            allowed_tools=["Read", "Write", "Edit", "Bash", "Grep", "Glob"],
            relative_dir=rel_dir,
            body=body,
            # Knowledge pack loaded by agents — hide from the / menu.
            user_invocable=False,
            # Team owns the body — never clobber on regenerate.
            preserve_on_regen=True,
        )

    # Merge MCP fragments
    mcp_inputs: dict[str, dict] = {}  # keyed by input id; later fragments don't override
    for frag in mcp_fragments:
        for name, server_config in (frag.get("mcpServers") or {}).items():
            if name in mcp_servers:
                continue
            mcp_servers[name] = MCPSpec(
                name=name,
                transport=server_config.get("type", "stdio"),
                command=server_config.get("command"),
                args=server_config.get("args"),
                url=server_config.get("url"),
                headers=server_config.get("headers"),
                env=server_config.get("env"),
            )
        # VS Code-style `inputs` declarations (promptString etc.) — carry through
        # so `${input:<id>}` placeholders in server args resolve at runtime.
        for inp in frag.get("inputs") or []:
            input_id = inp.get("id")
            if input_id and input_id not in mcp_inputs:
                mcp_inputs[input_id] = inp

    # Permissions baked from governance + user extras (minimal v0.1: just user extras)
    permissions.allow.extend(config.permissions.allow_extra)
    permissions.deny.extend(config.permissions.deny_extra)

    ir = HarnessIR(
        project=ProjectMetaIR(
            name=config.project.name,
            description=config.project.description,
            repo_root=config.project.repo_root,
        ),
        memory=memory,
        rules=list(rules.values()),
        skills=list(skills.values()),
        agents=list(agents.values()),
        hooks=hooks,
        mcp_servers=list(mcp_servers.values()),
        mcp_inputs=list(mcp_inputs.values()),
        permissions=permissions,
        env_required=[],
        metadata=GenMeta(
            template_version=config.template_version,
            harness_version=harness_version,
            generated_at=datetime.now(UTC),
            source_layers=source_layers,
        ),
    )
    # Stash hook script bodies on the IR via a private attribute. The emitter writes them.
    # (Pydantic models forbid extras; use the model's __pydantic_private__ slot via setattr.)
    object.__setattr__(ir, "_hook_scripts", hook_scripts)
    return ir


def _hookspec_from_settings_entry(event: str, matcher: str | None, handler: dict) -> HookSpec:
    """Convert a single settings.json hook entry back into a HookSpec."""
    return HookSpec(
        event=event,
        matcher=matcher,
        type=handler.get("type", "command"),
        command=handler.get("command"),
        url=handler.get("url"),
        headers=handler.get("headers"),
        allowed_env_vars=handler.get("allowedEnvVars"),
        server=handler.get("server"),
        tool=handler.get("tool"),
        input=handler.get("input"),
        prompt=handler.get("prompt"),
        model=handler.get("model"),
        timeout=handler.get("timeout"),
    )


def _render_or_read(env: Environment, layers: list[Layer], rel: str, ctx: dict) -> str:
    """Render Jinja templates; read static files verbatim. Last-wins shadowing
    is handled by `build_environment` already."""
    if is_jinja_template(rel):
        return env.get_template(rel).render(**ctx)
    # static file: read from highest-precedence layer
    for layer in reversed(existing_layers(layers)):
        candidate = layer.root / rel
        if candidate.exists():
            return candidate.read_text(encoding="utf-8")
    raise FileNotFoundError(rel)


def _build_skill_spec(out_rel: str, content: str) -> SkillSpec:
    fm, body = _split_frontmatter(content)
    relative_dir = "/".join(out_rel.split("/")[:-1])  # strip "/SKILL.md"
    return SkillSpec(
        body=body,
        relative_dir=relative_dir,
        **{k: v for k, v in fm.items() if v is not None},
    )


def _build_agent_spec(out_rel: str, content: str, *, default_model: str) -> AgentSpec:
    fm, body = _split_frontmatter(content)
    return AgentSpec(
        body=body,
        relative_path=out_rel,
        **{k: v for k, v in fm.items() if v is not None},
    )


def _build_rule_spec(out_rel: str, content: str) -> RuleSpec:
    fm, body = _split_frontmatter(content)
    return RuleSpec(
        relative_path=out_rel,
        body=body,
        paths=fm.get("paths"),
    )
